fn fixture(rel: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(rel)
}

fn count_group(nodes: &[Node], group: &str) -> usize {
    nodes.iter().filter(|n| n.group == group).count()
}

