    assert_eq!(count_group(&nodes, "interfaces"), 1);
    assert_eq!(count_group(&nodes, "types"), 1);
    assert_eq!(count_group(&nodes, "enums"), 1);
    assert_eq!(count_group(&nodes, "imports"), 2);
}

